package main

import (
	"fmt"
	"time"
)

func generateReceiveLog(msg string) string {
	// Simple sanitization: remove any characters that are not alphanumeric or spaces
	sanitizedMsg := ""
	for _, c := range msg {
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == ' ' {
			sanitizedMsg += string(c)
		}
	}
	return "[" + time.Now().Format(time.RFC3339) + "] Received: " + sanitizedMsg
}

func main() {
	fmt.Println(generateReceiveLog("Hello 123!"))
}

